"""图片预处理：Alpha 通道生成 + 色阶（PIL/NumPy 依赖）。"""

import numpy as np
from PIL import Image
from pathlib import Path


def make_gray_gamma(rgb_image):
    """sRGB → 线性 → BT.709 亮度 → sRGB 灰度通道（NumPy 向量化）。"""
    arr = np.asarray(rgb_image, dtype=np.float32) / 255.0
    low = arr <= 0.04045
    linear = np.where(low, arr / 12.92, np.power((arr + 0.055) / 1.055, 2.4))
    y_lin = 0.2126 * linear[:, :, 0] + 0.7152 * linear[:, :, 1] + 0.0722 * linear[:, :, 2]
    low_y = y_lin <= 0.0031308
    y_srgb = np.where(low_y, y_lin * 12.92, 1.055 * np.power(y_lin, 1.0 / 2.4) - 0.055)
    gray = np.clip(np.rint(y_srgb * 255.0), 0, 255).astype(np.uint8)
    return Image.fromarray(gray, mode="L")


def apply_preprocess(png_path, config, temp_dir):
    """PNG → TGA（Alpha 通道生成 + 色阶），返回生成的 TGA 路径。"""
    img = Image.open(png_path).convert("RGBA")
    rgb = img.convert("RGB")

    alpha_source = config.get("alpha_source", "gray")
    if alpha_source == "r":
        gray = img.getchannel("R")
    elif alpha_source == "g":
        gray = img.getchannel("G")
    elif alpha_source == "b":
        gray = img.getchannel("B")
    else:
        gray = make_gray_gamma(rgb)

    if config.get("levels_enabled"):
        ob = int(config.get("out_black", 0))
        ow = int(config.get("out_white", 255))
        if ob != ow:
            gray = gray.point(lambda v: 0 if v < ob else (255 if v > ow else int((v - ob) / (ow - ob) * 255)))

    result = Image.merge("RGBA", (*rgb.split(), gray))
    tga_path = Path(temp_dir) / f"{Path(png_path).stem}.tga"
    result.save(tga_path, format="TGA")
    return str(tga_path)
